"""Typed predicate expressions.

Predicates arrive as JSON expression arrays.  They are compiled once per
module into small closures so that every recorded witness can be checked
without re-walking the source form.  Scoping is lexical: an ``all`` binding
shadows an outer binding of the same name without touching it.
"""

from .ast import (Alias, Bool, Int, String, constant_value, values_equal)
from . import regex as pattern_language

COMPARISONS = ('eq', 'ne', 'lt', 'le', 'gt', 'ge')
ARITHMETIC = ('add', 'sub')
LOGICAL = ('and', 'or', 'implies')
BINARY = COMPARISONS + ARITHMETIC + LOGICAL


class ExpressionError(ValueError):
    """Raised when a predicate does not fit the documented grammar."""


def _truth(value):
    return bool(value)


def compile_expression(node, scope, types):
    """Compile one expression node into a `(type, function)` pair."""
    if not isinstance(node, list) or not node:
        raise ExpressionError('malformed expression')
    tag = node[0]
    if tag == 'var':
        name = node[1]
        if name not in scope:
            raise ExpressionError('unknown variable: ' + str(name))
        type = scope[name]
        return type, _var(name)
    if tag == 'const':
        type = types.get(node[1])
        value = constant_value(type, node[2])
        return type, _const(value)
    if tag == 'field':
        base_type, base = compile_expression(node[1], scope, types)
        base_type = base_type.inner()
        if base_type.kind != 'struct':
            raise ExpressionError('field of a non-struct value')
        field = node[2]
        field_type = base_type.field(field)
        return field_type, _field(base, field)
    if tag == 'index':
        base_type, base = compile_expression(node[1], scope, types)
        base_type = base_type.inner()
        if base_type.kind != 'array':
            raise ExpressionError('index of a non-array value')
        position = node[2]
        if not isinstance(position, int) or isinstance(position, bool):
            raise ExpressionError('index must be an integer')
        if position < 0 or position >= base_type.size:
            raise ExpressionError('index out of range')
        return base_type.element, _index(base, position)
    if tag == 'all':
        binding = node[1]
        base_type, base = compile_expression(node[2], scope, types)
        base_type = base_type.inner()
        if base_type.kind != 'array':
            raise ExpressionError('all over a non-array value')
        inner_scope = dict(scope)
        inner_scope[binding] = base_type.element
        _, body = compile_expression(node[3], inner_scope, types)
        return Bool(), _all(base, body, binding)
    if tag == 'match':
        base_type, base = compile_expression(node[1], scope, types)
        base_type = base_type.inner()
        if base_type.kind != 'string':
            raise ExpressionError('match of a non-string value')
        program = pattern_language.compile_pattern(node[2])
        return Bool(), _match(base, program)
    if tag == 'not':
        _, body = compile_expression(node[1], scope, types)
        return Bool(), _not(body)
    if tag in BINARY:
        left_type, left = compile_expression(node[1], scope, types)
        right_type, right = compile_expression(node[2], scope, types)
        return _binary(tag, left_type, left, right_type, right)
    raise ExpressionError('unknown expression form: ' + str(tag))


def _var(name):
    def evaluate(context):
        return context[name]
    return evaluate


def _const(value):
    def evaluate(context):
        return value
    return evaluate


def _field(base, field):
    def evaluate(context):
        return base(context)[field]
    return evaluate


def _index(base, position):
    def evaluate(context):
        return base(context)[position]
    return evaluate


def _all(base, body, binding):
    def evaluate(context):
        items = base(context)
        if not items:
            return True
        inner = dict(context)
        for item in items:
            inner[binding] = item
            if not _truth(body(inner)):
                return False
        return True
    return evaluate


def _match(base, program):
    def evaluate(context):
        return pattern_language.fullmatch(program, base(context))
    return evaluate


def _not(body):
    def evaluate(context):
        return not _truth(body(context))
    return evaluate


def _binary(op, left_type, left, right_type, right):
    if op in COMPARISONS:
        compare_type = left_type.inner()
        if op == 'eq':
            def evaluate(context):
                return values_equal(compare_type, left(context), right(context))
        elif op == 'ne':
            def evaluate(context):
                return not values_equal(compare_type, left(context), right(context))
        else:
            def evaluate(context):
                one = left(context)
                two = right(context)
                if op == 'lt':
                    return one < two
                if op == 'le':
                    return one <= two
                if op == 'gt':
                    return one > two
                return one >= two
        return Bool(), evaluate
    if op in ARITHMETIC:
        number_type = left_type.inner()
        if number_type.kind != 'int':
            raise ExpressionError('arithmetic on a non-integer value')
        modulus = number_type.modulus()
        if op == 'add':
            def evaluate(context):
                return (left(context) + right(context)) % modulus
        else:
            def evaluate(context):
                return (left(context) - right(context)) % modulus
        return number_type, evaluate
    if op == 'and':
        def evaluate(context):
            return _truth(left(context)) and _truth(right(context))
    elif op == 'or':
        def evaluate(context):
            return _truth(left(context)) or _truth(right(context))
    else:
        def evaluate(context):
            return (not _truth(left(context))) or _truth(right(context))
    return Bool(), evaluate


def compile_predicate(node, scope, types):
    """Compile a predicate into a function of the visible variables."""
    if node is None:
        return None
    _, evaluate = compile_expression(node, scope, types)
    return evaluate
